from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    background = counts.most_common(1)[0][0]
    marked = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] not in (0, background)]
    if not marked:
        return [row[:] for row in grid]
    r0 = min(r for r, c, _ in marked)
    c0 = min(c for r, c, _ in marked)
    color = marked[0][2]
    shape = {(r-r0, c-c0) for r, c, _ in marked}
    mh = max(r for r, c in shape) + 1
    mw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out

